import { Component, Element, Host, Prop, h } from "@stencil/core";
import retargetEvents from "react-shadow-dom-retarget-events";
import { renderChart } from "./RenderChart";

/**
 * @since 0.0.12
 * @status experimental
 *
 */
@Component({
	tag: "hbr-heatmap",
	styleUrl: "heatmap.scss",
	shadow: true,
})
export class HbrHeatmap {
	heatmap: HTMLElement;

	/** Chart configuration object. Refer to https://nivo.rocks/heatmap */
	@Prop() config: any = { data: [] };

	/** Chart width */
	@Prop() width = "100%";

	/** Chart height */
	@Prop() height = "360px";

	@Element() private el: HTMLHbrHeatmapElement;

	componentDidLoad() {
		this.createChart();
		retargetEvents(this.el.shadowRoot);
	}

	componentShouldUpdate() {
		this.createChart();
		return false;
	}

	createChart() {
		const root = this.el.shadowRoot.querySelector("div");
		renderChart({
			el: root,
			config: this.config,
		});
		return root;
	}

	render() {
		this.el.style.width = this.width;
		this.el.style.height = this.height;

		return (
			<Host>
				<div
					ref={(el) => (this.heatmap = el)}
					style={{ width: this.width, height: this.height }}
				></div>
			</Host>
		);
	}
}
