import { ResponsiveHeatMap as Heatmap } from "@harbor-charts/heatmap";
import merge from "deepmerge";
import React from "react";
import { createRoot } from "react-dom/client";
import { getBaseConfig } from "../../../utils/charts";
import { combineMergeArray } from "../../../utils/combineMergeArray";
import getLayers from "./util/getLayers";

function getHeatmapBaseConfig({ config }) {
	return {
		emptyColor: "transparent",
		axisLeft: {
			tickSize: 0,
			tickPadding: 10,
		},
		axisTop: {
			tickSize: 0,
			tickPadding: 10,
		},
		forceSquare: true,
		animate: false,
		motionConfig: "wobbly",
		motionStiffness: 80,
		motionDamping: 9,
		layers: getLayers(config),
		enableGridX: false,
		isInteractive: true,
		legends: [
			{
				anchor: "bottom",
				translateX: 0,
				translateY: 30,
				length: 400,
				thickness: 8,
				direction: "row",
				tickPosition: "after",
				tickSize: 3,
				tickSpacing: 4,
				tickOverlap: false,
				titleOffset: 4,
			},
		],
	};
}

export function renderChart(params: any) {
	const { el, config } = params;
	const _config = merge.all(
		[getBaseConfig(), getHeatmapBaseConfig(params), config],
		{
			arrayMerge: combineMergeArray,
		},
	);

	const root = createRoot(el);
	root.render(React.createElement(Heatmap, _config, null));
}
