interface Config {
	layers: [] | null;
	legends: [] | null;
}

export default function getLayers(config: Config) {
	const layers = ["grid", "axes", "cells"];
	const legendExist =
		(Array.isArray(config.legends) && 0 < config.legends.length) ||
		config.legends === undefined;
	let _layers = layers;
	if (legendExist) {
		_layers.push("legends");
	}
	if (config.layers && Array.isArray(config.layers)) {
		_layers = config.layers.map((layer) => {
			return layer;
		});
		delete config.layers;
	}
	return _layers;
}
